def seed_markets(apps, schema_editor):
    Market = apps.get_model("agent", "Market")
    Lead = apps.get_model("agent", "Lead")
    for i, (name, enabled, currency, code, tz, cities, postal, note) in enumerate(MARKETS):
        Market.objects.get_or_create(
            name=name,
            defaults=dict(enabled=enabled, currency=currency, calling_code=code, timezone=tz,
                          cities="\n".join(cities), requires_postal_address=postal, rules_note=note, sort=i),
        )
    # Link existing leads to a market by their city name.
    for market in Market.objects.all():
        for city in market.cities.splitlines():
            short = city.split(",")[0].strip()
            if not short:
                continue
            Lead.objects.filter(market__isnull=True, source="osm").filter(
                models.Q(city__iexact=city.strip()) | models.Q(city__iexact=short) | models.Q(city__istartswith=short + ",")
            ).update(market=market)


